#include <bits/stdc++.h>
using namespace std;
const int mod=998244353;
void solve(){
    int n;
    cin>>n;
    vector<vector<int>>pos(n+1);
    for(int i=1;i<=n;i++){
        int x;
        cin>>x;
        pos[x].push_back(i);
    }
    vector<int>dp(1,1);
    auto pre=[&](int i,int x,int l){
        int r=x-l;
        int e=min(i,l);
        int f=max(0,i-(n-r));
        return e+f;
    };
    auto suf=[&](int i,int x,int l){
        int r=x-l;
        int g=max(0,l-i+1);
        int h=min(r,n-i+1);
        return g+h;
    };
    for(int x=1;x<n;x++){
        vector<int>ndp(x+1,0);
        for(int l=0;l<x;l++){
            if(dp[l]==0) continue;
            for(int y=0;y<=1;y++){
                int nl=l+y;
                bool ok=true;
                for(int i:pos[x]){
                    int p=(i+1)/2;
                    int s=(n-i+2)/2;
                    bool a=pre(i,x-1,l)<p && pre(i,x,nl)>=p;
                    bool b=suf(i,x-1,l)<s && suf(i,x,nl)>=s;
                    if(!a && !b){
                        ok=false;
                        break;
                    }
                }
                if(ok){
                    ndp[nl]+=dp[l];
                    if(ndp[nl]>=mod) ndp[nl]-=mod;
                }
            }
        }
        dp.swap(ndp);
    }
    long long ans=0;
    for(int l=0;l<n;l++){
        if(dp[l]==0) continue;
        bool ok=true;
        for(int i:pos[n]){
            int p=(i+1)/2;
            int s=(n-i+2)/2;
            bool a=pre(i,n-1,l)<p;
            bool b=suf(i,n-1,l)<s;
            if(!a && !b){
                ok=false;
                break;
            }
        }
        if(ok){
            ans=(ans+dp[l])%mod;
        }
    }
    cout<<ans<<'\n';
}
int main() {
	ios::sync_with_stdio(false);
	cin.tie(nullptr);
	int t;
	cin>>t;
	while(t--){
	    solve();
	}
	return 0;
}
